之前对缓存命中率进行过调优，性能应该不差。你看看能不能移植到NEON

#version 460

/*{{injected_macros}}*/

layout(std430, binding=0) buffer Buffer0 {
    float error[CANVAS_SIZE_X * CANVAS_SIZE_Y];
};

layout(std430, binding=1) buffer LineData {
    uint n_groups_x, n_groups_y, n_groups_z;
    vec2 line_p1, line_p2;
    int line_y_start, line_y_end;
    float line_x_width;
    float line_original_r;
    bool line_horizontal;
};

layout(local_size_x = LINE_RASTERIZATION_LOCAL_SIZE) in;

float distance_to_line(vec2 p, vec2 a, vec2 b) {
    vec2 ab = b - a;
    vec2 ap = p - a;
    float t = dot(ap, ab)/dot(ab, ab);
    vec2 c;
    if (t<0) {
        c = a;
    }
    else if (t>1) {
        c = b;
    }
    else {
        c = a + t * ab;
    }
    return length(p-c);
}

#define HALF_LINE_WIDTH (LINE_WIDTH/2)

float weight(float i) {
    if (i > HALF_LINE_WIDTH + 0.25) {
        return 0.0;
    }
    if (i < HALF_LINE_WIDTH - 0.25) {
        return 1.0;
    }
    return (HALF_LINE_WIDTH + 0.25f - i) / 0.5f ;
}

void main() {
    int j = int(gl_GlobalInvocationID.y) + line_y_start;
    if (j > line_y_end) return;
    if (j < 0 || j >= CANVAS_SIZE_Y) return;

    vec2 p1 = line_p1;
    vec2 p2 = line_p2;
    vec2 r = p2 - p1;
    int x_start;
    if (line_horizontal) {
        x_start = int(floor(min(p1.x, p2.x) - HALF_LINE_WIDTH)); 
    }
    else {
        x_start = int(floor(p1.x + (float(j) - p1.y) / r.y * r.x - line_x_width / 2.0));
    }
    int i = int(gl_GlobalInvocationID.x) + x_start;
    if (i < 0 || i >= CANVAS_SIZE_X) return;

    float d = distance_to_line(vec2(i, j), p1, p2);
    float w = weight(d);

    error[j * CANVAS_SIZE_X + i] -= (w * BEAM_POWER / line_original_r);
}

