实际上这个shader还有前一级shader，用于计算一些必要的参数

```glsl
    { // pre-process for line rasterization pass
        #define EPSILON (1e-8f)

        vec2 r = p2 - p1;
        float original_r = length(r);

        { // Liang-Barsky line clipping
            bool out_of_rect = false;
            float t0 = 0.0;
            float t1 = 1.0;
            float t;

            #define LIANG_BARSKY(p, q) { \
                if (abs((p)) < EPSILON) { \
                    if ((q) < 0) out_of_rect = true; \
                } else { \
                    t = (q) / (p); \
                    if ((p) < 0) t0 = max(t0, t); \
                    else t1 = min(t1, t); \
                } \
            } // end of LIANG_BARSKY

            LIANG_BARSKY(-r.x, p1.x - 0.0);
            LIANG_BARSKY(r.x, float(CANVAS_SIZE_X) - p1.x);
            LIANG_BARSKY(-r.y, p1.y - 0.0);
            LIANG_BARSKY(r.y, float(CANVAS_SIZE_Y) - p1.y);

            if (!out_of_rect && t0 <= t1) {
                // update clipped line
                p2 = p1 + t1 * r;
                p1 = p1 + t0 * r;
                r = p2 - p1;
            }
            else {
                // line out of rect
                // skip the rasterization pass
                n_groups_x = 0;
                return;
            }
        }

        int y_start = max(int(floor(min(p1.y, p2.y) - LINE_WIDTH)), 0);
        int y_end = min(int(ceil(max(p1.y, p2.y) + LINE_WIDTH)), CANVAS_SIZE_Y);
        uint n_y = uint(y_end - y_start + 1);

        float dy = abs(r.y);
        float dx = abs(r.x);
        bool horizontal = dy < EPSILON;
        float x_width = horizontal ? dx + LINE_WIDTH : LINE_WIDTH * length(r) / dy;
        uint n_x = uint(ceil(ceil(x_width) / LINE_RASTERIZATION_LOCAL_SIZE));

        // write to buffer
        n_groups_x = n_x;
        n_groups_y = n_y;
        n_groups_z = 1;
        line_p1 = p1;
        line_p2 = p2;
        line_y_start = y_start;
        line_y_end = y_end;
        line_x_width = x_width;
        line_original_r = original_r;
        line_horizontal = horizontal;
    }
